-- Prevent one Canvas API token from being connected to more than one row.
-- The fingerprint is keyed and generated by the application because SQL
-- migrations must never need access to the decrypted Canvas token.
ALTER TABLE canvas_connections
    ADD COLUMN IF NOT EXISTS token_fingerprint VARCHAR;

CREATE UNIQUE INDEX IF NOT EXISTS uq_canvas_token_fingerprint
    ON canvas_connections(token_fingerprint)
    WHERE token_fingerprint IS NOT NULL;
